messages=(char **) handle;
if (*messages == (char *) NULL)
*messages=(char *) AcquireQuantumMemory((size_t) length+1,sizeof(char *));
else
{
offset=(ssize_t) strlen(*messages);
*messages=(char *) ResizeQuantumMemory(*messages,(size_t) offset+length+1,
sizeof(char *));
}
