printf( "|                                       |\n" );
printf( "| sql-statement                         |\n" );
printf( "| help [tablename]                      |\n" );
printf( "| quit                                  |\n" );
printf( "|                                       |\n" );
printf( "+---------------------------------------+\n" );
}
do
{
if ( !bBatch )
#ifndef HAVE_READLINE
printf( "SQL> " );
#else
{
char *line;
int malloced;
line=readline("SQL> ");
if ( !line )
{
malloced = 1;
line = strdup( "quit" );
}
else
{
malloced = 0;
}
strncpy(szSQL, line, buffer_size );
add_history(line);
if ( malloced )
{
free(line);
}
}
else
#endif
{
char *line;
int malloced;
line = fgets( szSQL, buffer_size, stdin );
if ( !line )
{
malloced = 1;
line = strdup( "quit" );
}
else
{
malloced = 0;
}
strncpy(szSQL, line, buffer_size );
if ( malloced )
{
free(line);
}
}
while ( (pEscapeChar=(char*)strchr(szSQL, '\n')) != NULL || (pEscapeChar=(char*)strchr(szSQL, '\r')) != NULL )
*pEscapeChar = ' ';
if ( szSQL[1] != '\0' )
{
