void ResourceDispatcherHostImpl::BeginSaveFile(
const GURL& url,
const content::Referrer& referrer,
int child_id,
int route_id,
ResourceContext* context) {
if (is_shutdown_)
return;
char url_buf[128];
base::strlcpy(url_buf, url.spec().c_str(), arraysize(url_buf));
base::debug::Alias(url_buf);
CHECK(ContainsKey(active_resource_contexts_, context));
scoped_refptr<ResourceHandler> handler(
new SaveFileResourceHandler(child_id,
route_id,
url,
save_file_manager_.get()));
request_id_--;
const net::URLRequestContext* request_context = context->GetRequestContext();
bool known_proto =
request_context->job_factory()->IsHandledURL(url);
if (!known_proto) {
NOTREACHED();
return;
}
net::URLRequest* request = new net::URLRequest(url, this);
request->set_method("GET");
request->set_referrer(MaybeStripReferrer(referrer.url).spec());
webkit_glue::ConfigureURLRequestForReferrerPolicy(request, referrer.policy);
request->set_load_flags(net::LOAD_PREFERRING_CACHE);
request->set_context(context->GetRequestContext());
ResourceRequestInfoImpl* extra_info =
CreateRequestInfo(handler, child_id, route_id, false, context);
extra_info->AssociateWithRequest(request);
BeginRequestInternal(request);
}

ResultExpr GpuProcessPolicy::EvaluateSyscall(int sysno) const {
switch (sysno) {
#if !defined(OS_CHROMEOS)
case __NR_ftruncate:
#endif
case __NR_ioctl:
return Allow();
case __NR_mincore:
if (allow_mincore_) {
return Allow();
} else {
return SandboxBPFBasePolicy::EvaluateSyscall(sysno);
}
#if defined(__i386__) || defined(__x86_64__) || defined(__mips__)
case __NR_mmap:
#endif
case __NR_mprotect:
case __NR_prctl:
return Allow();
#if !defined(__aarch64__)
case __NR_access:
case __NR_open:
#endif
case __NR_faccessat:
case __NR_openat:
DCHECK(broker_process_);
return Trap(GpuSIGSYS_Handler, broker_process_);
case __NR_sched_getaffinity:
case __NR_sched_setaffinity:
return sandbox::RestrictSchedTarget(GetPolicyPid(), sysno);
default:
if (SyscallSets::IsEventFd(sysno))
return Allow();
return SandboxBPFBasePolicy::EvaluateSyscall(sysno);
}
}

static jboolean sspReplyNative(JNIEnv *env, jobject obj, jbyteArray address,
jint type, jboolean accept, jint passkey) {
ALOGV("%s:",__FUNCTION__);
jbyte *addr;
jboolean result = JNI_FALSE;
if (!sBluetoothInterface) return result;
addr = env->GetByteArrayElements(address, NULL);
if (addr == NULL) {
jniThrowIOException(env, EINVAL);
return result;
}
int ret = sBluetoothInterface->ssp_reply((bt_bdaddr_t *)addr,
(bt_ssp_variant_t) type, accept, passkey);
env->ReleaseByteArrayElements(address, addr, 0);
result = (ret == BT_STATUS_SUCCESS) ? JNI_TRUE : JNI_FALSE;
return result;
}

