"\\u1810-\\u1819\\u1820-\\u1877\\u1880-\\u18AA"
"\\u18B0-\\u18F5"
"\\u2D30-\\u2D67\\u2D7F"
"\\uA000-\\uA48C"
"\\U00016F00-\\U00016F44\\U00016F50-\\U00016F7E"
"\\U00016F8F-\\U00016F9F]",
-1, US_INV),
