x += args[0];
y += args[1];
cff_builder_add_point( builder, x, y, 1 );
args = stack;
}
break;
case cff_op_hflex1:
{
FT_Pos start_y;
FT_TRACE4(( " hflex1\n" ));
if ( cff_builder_start_point( builder, x, y ) ||
check_points( builder, 6 )               )
goto Fail;
start_y = y;
x += args[0];
y += args[1];
cff_builder_add_point( builder, x, y, 0 );
x += args[2];
y += args[3];
cff_builder_add_point( builder, x, y, 0 );
x += args[4];
cff_builder_add_point( builder, x, y, 1 );
x += args[5];
cff_builder_add_point( builder, x, y, 0 );
x += args[6];
y += args[7];
cff_builder_add_point( builder, x, y, 0 );
x += args[8];
y  = start_y;
cff_builder_add_point( builder, x, y, 1 );
args = stack;
break;
}
case cff_op_hflex:
{
FT_Pos start_y;
FT_TRACE4(( " hflex\n" ));
if ( cff_builder_start_point( builder, x, y ) ||
check_points( builder, 6 )               )
goto Fail;
start_y = y;
x += args[0];
cff_builder_add_point( builder, x, y, 0 );
x += args[1];
y += args[2];
cff_builder_add_point( builder, x, y, 0 );
x += args[3];
cff_builder_add_point( builder, x, y, 1 );
x += args[4];
cff_builder_add_point( builder, x, y, 0 );
x += args[5];
y  = start_y;
cff_builder_add_point( builder, x, y, 0 );
x += args[6];
cff_builder_add_point( builder, x, y, 1 );
args = stack;
break;
}
case cff_op_flex1:
{
FT_Pos     start_x, start_y;
FT_Fixed   dx = 0, dy = 0;
FT_Int     horizontal, count;
FT_Fixed*  temp;
FT_TRACE4(( " flex1\n" ));
if ( cff_builder_start_point( builder, x, y ) ||
check_points( builder, 6 )               )
goto Fail;
start_x = x;
start_y = y;
temp = args;
for ( count = 5; count > 0; count-- )
{
dx += temp[0];
dy += temp[1];
temp += 2;
}
