goto trunctlv;
tmp-=ext_is_len;
tptr+=ext_is_len;
}
break;
case ISIS_TLV_EXT_IS_REACH:
while (tmp >= NODE_ID_LEN+3+1) {
ext_is_len = isis_print_ext_is_reach(ndo, tptr, "\n\t      ", tlv_type);
if (ext_is_len == 0)
goto trunctlv;
tmp-=ext_is_len;
tptr+=ext_is_len;
}
break;
