HTTPSession::onEgressMessageFinished(HTTPTransaction* txn, bool withRST) {
  // If the semantics of the protocol don't permit more messages
  // to be read or sent on this connection, close the socket in one or
  // more directions.
  CHECK(!transactions_.empty());

  if (infoCallback_) {
    infoCallback_->onRequestEnd(*this, txn->getMaxDeferredSize());
  }
  auto oldStreamCount = getPipelineStreamCount();
  decrementTransactionCount(txn, false, true);
  if (withRST || ((!codec_->isReusable() || readsShutdown()) &&
                  transactions_.size() == 1)) {
    // We should shutdown reads if we are closing with RST or we aren't
    // interested in any further messages (ie if we are a downstream session).
    // Upgraded sessions have independent ingress and egress, and the reads
    // need not be shutdown on egress finish.
    if (withRST) {
      // Let any queued writes complete, but send a RST when done.
      VLOG(4) << *this << " resetting egress after this message";
      resetAfterDrainingWrites_ = true;
      setCloseReason(ConnectionCloseReason::TRANSACTION_ABORT);
      shutdownTransport(true, true);
    } else {
      // the reason is already set (either not reusable or readshutdown).

      // Defer normal shutdowns until the end of the loop.  This
      // handles an edge case with direct responses with Connection:
      // close served before ingress EOM.  The remainder of the ingress
      // message may be in the parse loop, so give it a chance to
      // finish out and avoid a kErrorEOF

      // we can get here during shutdown, in that case do not schedule a
      // shutdown callback again
      if (!shutdownTransportCb_) {
        // Just for safety, the following bumps the refcount on this session
        // to keep it live until the loopCb runs
        shutdownTransportCb_.reset(new ShutdownTransportCallback(this));
        sock_->getEventBase()->runInLoop(shutdownTransportCb_.get(), true);
      }
    }
  } else {
    maybeResumePausedPipelinedTransaction(oldStreamCount,
                                          txn->getSequenceNumber());
  }
}

void BackendIO::ExecuteBackendOperation() {
switch (operation_) {
case OP_INIT:
result_ = backend_->SyncInit();
break;
case OP_OPEN: {
scoped_refptr<EntryImpl> entry;
result_ = backend_->SyncOpenEntry(key_, &entry);
*entry_ptr_ = LeakEntryImpl(std::move(entry));
break;
}
case OP_CREATE: {
scoped_refptr<EntryImpl> entry;
result_ = backend_->SyncCreateEntry(key_, &entry);
*entry_ptr_ = LeakEntryImpl(std::move(entry));
break;
}
case OP_DOOM:
result_ = backend_->SyncDoomEntry(key_);
break;
case OP_DOOM_ALL:
result_ = backend_->SyncDoomAllEntries();
break;
case OP_DOOM_BETWEEN:
result_ = backend_->SyncDoomEntriesBetween(initial_time_, end_time_);
break;
case OP_DOOM_SINCE:
result_ = backend_->SyncDoomEntriesSince(initial_time_);
break;
case OP_SIZE_ALL:
result_ = backend_->SyncCalculateSizeOfAllEntries();
break;
case OP_OPEN_NEXT: {
scoped_refptr<EntryImpl> entry;
result_ = backend_->SyncOpenNextEntry(iterator_, &entry);
*entry_ptr_ = LeakEntryImpl(std::move(entry));
break;
}
case OP_END_ENUMERATION:
backend_->SyncEndEnumeration(std::move(scoped_iterator_));
result_ = net::OK;
break;
case OP_ON_EXTERNAL_CACHE_HIT:
backend_->SyncOnExternalCacheHit(key_);
result_ = net::OK;
break;
case OP_CLOSE_ENTRY:
entry_->Release();
result_ = net::OK;
break;
case OP_DOOM_ENTRY:
entry_->DoomImpl();
result_ = net::OK;
break;
case OP_FLUSH_QUEUE:
result_ = net::OK;
break;
case OP_RUN_TASK:
task_.Run();
result_ = net::OK;
break;
default:
NOTREACHED() << "Invalid Operation";
result_ = net::ERR_UNEXPECTED;
}
DCHECK_NE(net::ERR_IO_PENDING, result_);
NotifyController();
}

Status explain(OperationContext* opCtx,
               const OpMsgRequest& request,
               ExplainOptions::Verbosity verbosity,
               BSONObjBuilder* out) const override {
    std::string dbname = request.getDatabase().toString();
    const BSONObj& cmdObj = request.body;
    // Acquire locks and resolve possible UUID. The RAII object is optional, because in the case
    // of a view, the locks need to be released.
    boost::optional<AutoGetCollectionForReadCommand> ctx;
    ctx.emplace(opCtx,
                CommandHelpers::parseNsOrUUID(dbname, cmdObj),
                AutoGetCollection::ViewMode::kViewsPermitted);
    const auto nss = ctx->getNss();

    // Parse the command BSON to a QueryRequest.
    const bool isExplain = true;
    auto qrStatus = QueryRequest::makeFromFindCommand(nss, cmdObj, isExplain);
    if (!qrStatus.isOK()) {
        return qrStatus.getStatus();
    }

    // Finish the parsing step by using the QueryRequest to create a CanonicalQuery.
    const ExtensionsCallbackReal extensionsCallback(opCtx, &nss);
    const boost::intrusive_ptr<ExpressionContext> expCtx;
    auto statusWithCQ =
        CanonicalQuery::canonicalize(opCtx,
                                     std::move(qrStatus.getValue()),
                                     expCtx,
                                     extensionsCallback,
                                     MatchExpressionParser::kAllowAllSpecialFeatures);
    if (!statusWithCQ.isOK()) {
        return statusWithCQ.getStatus();
    }
    std::unique_ptr<CanonicalQuery> cq = std::move(statusWithCQ.getValue());

    if (ctx->getView()) {
        // Relinquish locks. The aggregation command will re-acquire them.
        ctx.reset();

        // Convert the find command into an aggregation using $match (and other stages, as
        // necessary), if possible.
        const auto& qr = cq->getQueryRequest();
        auto viewAggregationCommand = qr.asAggregationCommand();
        if (!viewAggregationCommand.isOK())
            return viewAggregationCommand.getStatus();

        // Create the agg request equivalent of the find operation, with the explain verbosity
        // included.
        auto aggRequest = AggregationRequest::parseFromBSON(
            nss, viewAggregationCommand.getValue(), verbosity);
        if (!aggRequest.isOK()) {
            return aggRequest.getStatus();
        }

        try {
            return runAggregate(
                opCtx, nss, aggRequest.getValue(), viewAggregationCommand.getValue(), *out);
        } catch (DBException& error) {
            if (error.code() == ErrorCodes::InvalidPipelineOperator) {
                return {ErrorCodes::InvalidPipelineOperator,
                        str::stream() << "Unsupported in view pipeline: " << error.what()};
            }
            return error.toStatus();
        }
    }

    // The collection may be NULL. If so, getExecutor() should handle it by returning an
    // execution tree with an EOFStage.
    Collection* const collection = ctx->getCollection();

    // We have a parsed query. Time to get the execution plan for it.
    auto statusWithPlanExecutor = getExecutorFind(opCtx, collection, nss, std::move(cq));
    if (!statusWithPlanExecutor.isOK()) {
        return statusWithPlanExecutor.getStatus();
    }
    auto exec = std::move(statusWithPlanExecutor.getValue());

    // Got the execution tree. Explain it.
    Explain::explainStages(exec.get(), collection, verbosity, out);
    return Status::OK();
}

v8::Local<v8::Value> PrivateScriptRunner::runDOMMethod(ScriptState* scriptState, ScriptState* scriptStateInUserScript, const char* className, const char* methodName, v8::Local<v8::Value> holder, int argc, v8::Local<v8::Value> argv[])
{
v8::Local<v8::Object> classObject = classObjectOfPrivateScript(scriptState, className);
v8::Local<v8::Value> method;
if (!classObject->Get(scriptState->context(), v8String(scriptState->isolate(), methodName)).ToLocal(&method) || !method->IsFunction()) {
fprintf(stderr, "Private script error: Target DOM method was not found. (Class name = %s, Method name = %s)\n", className, methodName);
RELEASE_NOTREACHED();
}
initializeHolderIfNeeded(scriptState, classObject, holder);
v8::TryCatch block(scriptState->isolate());
v8::Local<v8::Value> result;
if (!V8ScriptRunner::callFunction(v8::Local<v8::Function>::Cast(method), scriptState->getExecutionContext(), holder, argc, argv, scriptState->isolate()).ToLocal(&result)) {
rethrowExceptionInPrivateScript(scriptState->isolate(), block, scriptStateInUserScript, ExceptionState::ExecutionContext, methodName, className);
block.ReThrow();
return v8::Local<v8::Value>();
}
return result;
}

